'use client';
import { useState } from 'react';

// 👑 ADMIN EMAIL
const ADMIN_EMAIL = "utkarshpawar789@gmail.com"; // Apni email daalo

export default function Home() {
  const [user, setUser] = useState({ email: 'user@gmail.com' });
    const [cart, setCart] = useState([]);
      const [search, setSearch] = useState('');
        const [selectedBrand, setSelectedBrand] = useState('All');
          const [showOrderSuccess, setShowOrderSuccess] = useState(false);

            // Clean Sample Data - Badme Supabase Se Dynamically Aayenge
              const products = [
                  { id: 1, name: 'iPhone 15 Pro Max 256GB', brand: 'Apple', price: 134900, originalPrice: 159900, rating: '4.9', image: 'https://images.unsplash.com/photo-1695048133142-1a20484d2569?w=500' },
                      { id: 2, name: 'Samsung Galaxy S24 Ultra', brand: 'Samsung', price: 129999, originalPrice: 144999, rating: '4.8', image: 'https://images.unsplash.com/photo-1610945265064-0e34e5519bbf?w=500' },
                          { id: 3, name: 'boAt Airdopes 141 TWS', brand: 'boAt', price: 1299, originalPrice: 4490, rating: '4.5', image: 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=500' },
                              { id: 4, name: 'Pilgrim 24K Gold Facial Serum', brand: 'Pilgrim', price: 649, originalPrice: 950, rating: '4.7', image: 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?w=500' },
                                ];

                                  const filtered = products.filter(p => 
                                      (selectedBrand === 'All' || p.brand === selectedBrand) &&
                                          p.name.toLowerCase().includes(search.toLowerCase())
                                            );

                                              return (
                                                  <div style={{ backgroundColor: '#0f172a', color: '#ffffff', minHeight: '100vh', fontFamily: 'sans-serif' }}>
                                                        
                                                              {/* Top Banner */}
                                                                    <div style={{ backgroundColor: '#dc2626', color: '#ffffff', textAlign: 'center', padding: '8px', fontSize: '13px', fontWeight: 'bold' }}>
                                                                            🚚 Guaranteed Express Delivery within 7 Days across India!
                                                                                  </div>

                                                                                        {/* Header */}
                                                                                              <div style={{ padding: '15px 20px', backgroundColor: '#1e293b', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '10px' }}>
                                                                                                      <div style={{ fontSize: '22px', fontWeight: '900', color: '#a855f7' }}>ZENVRO STORE</div>
                                                                                                              
                                                                                                                      <input 
                                                                                                                                type="text" 
                                                                                                                                          placeholder="Search products..." 
                                                                                                                                                    value={search}
                                                                                                                                                              onChange={(e) => setSearch(e.target.value)}
                                                                                                                                                                        style={{ padding: '8px 15px', borderRadius: '8px', border: '1px solid #475569', backgroundColor: '#0f172a', color: '#fff', width: '250px' }}
                                                                                                                                                                                />

                                                                                                                                                                                        <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
                                                                                                                                                                                                  {user?.email === ADMIN_EMAIL && (
                                                                                                                                                                                                              <button style={{ backgroundColor: '#ef4444', color: '#fff', border: 'none', padding: '6px 12px', borderRadius: '6px', fontSize: '12px', cursor: 'pointer' }}>
                                                                                                                                                                                                                            👑 Admin
                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                            <div style={{ fontSize: '14px', fontWeight: 'bold' }}>
                                                                                                                                                                                                                                                                        🛒 Cart ({cart.length})
                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                      {/* Categories */}
                                                                                                                                                                                                                                                                                                            <div style={{ display: 'flex', justifyContent: 'center', gap: '10px', padding: '15px', overflowX: 'auto' }}>
                                                                                                                                                                                                                                                                                                                    {['All', 'Apple', 'Samsung', 'boAt', 'Pilgrim'].map((b) => (
                                                                                                                                                                                                                                                                                                                              <button 
                                                                                                                                                                                                                                                                                                                                          key={b} 
                                                                                                                                                                                                                                                                                                                                                      onClick={() => setSelectedBrand(b)}
                                                                                                                                                                                                                                                                                                                                                                  style={{
                                                                                                                                                                                                                                                                                                                                                                                padding: '8px 16px',
                                                                                                                                                                                                                                                                                                                                                                                              borderRadius: '20px',
                                                                                                                                                                                                                                                                                                                                                                                                            border: 'none',
                                                                                                                                                                                                                                                                                                                                                                                                                          backgroundColor: selectedBrand === b ? '#a855f7' : '#334155',
                                                                                                                                                                                                                                                                                                                                                                                                                                        color: '#ffffff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                      fontWeight: 'bold',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cursor: 'pointer'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {b}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {/* Products Grid */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '20px', padding: '20px', maxWidth: '1200px', margin: '0 auto' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {filtered.map((item) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const discount = Math.round(((item.originalPrice - item.price) / item.originalPrice) * 100);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div key={item.id} style={{ backgroundColor: '#1e293b', borderRadius: '12px', padding: '15px', border: '1px solid #334155', display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div style={{ position: 'relative', width: '100%', height: '180px', borderRadius: '8px', overflow: 'hidden', marginBottom: '10px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <img src={item.image} alt={item.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span style={{ position: 'absolute', top: '8px', left: '8px', backgroundColor: '#dc2626', color: '#fff', fontSize: '10px', padding: '2px 6px', borderRadius: '4px', fontWeight: 'bold' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {discount}% OFF
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={{ fontSize: '12px', color: '#a855f7', fontWeight: 'bold' }}>{item.brand}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={{ fontSize: '15px', fontWeight: 'bold', margin: '5px 0' }}>{item.name}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={{ fontSize: '12px', color: '#facc15' }}>⭐ {item.rating} / 5.0</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={{ fontSize: '11px', color: '#4ade80', marginTop: '6px' }}>🚚 Delivery within 7 Days</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div style={{ marginTop: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span style={{ fontSize: '16px', fontWeight: 'bold' }}>₹{item.price.toLocaleString('en-IN')}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <span style={{ fontSize: '12px', color: '#94a3b8', textDecoration: 'line-through', marginLeft: '6px' }}>₹{item.originalPrice.toLocaleString('en-IN')}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onClick={() => setCart([...cart, item])}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={{ backgroundColor: '#a855f7', color: '#fff', border: 'none', padding: '8px 14px', borderRadius: '6px', fontWeight: 'bold', cursor: 'pointer' }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Add
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {/* Floating Checkout */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {cart.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div style={{ position: 'fixed', bottom: '20px', right: '20px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onClick={() => { setShowOrderSuccess(true); setCart([]); }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style={{ backgroundColor: '#22c55e', color: '#fff', padding: '12px 24px', borderRadius: '30px', border: 'none', fontWeight: 'bold', fontSize: '15px', cursor: 'pointer', boxShadow: '0 4px 15px rgba(0,0,0,0.4)' }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Place Order ({cart.length}) ➔
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* Success Modal */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {showOrderSuccess && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.8)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '20px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div style={{ backgroundColor: '#1e293b', padding: '30px', borderRadius: '16px', textContent: 'center', maxWidth: '400px', width: '100%', textAlign: 'center', border: '1px solid #22c55e' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div style={{ fontSize: '40px', marginBottom: '10px' }}>🎉</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h2 style={{ fontSize: '20px', fontWeight: 'bold', color: '#22c55e' }}>Congratulations!</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p style={{ fontSize: '14px', color: '#cbd5e1', margin: '10px 0' }}>Your order has been placed successfully.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div style={{ backgroundColor: '#0f172a', padding: '10px', borderRadius: '8px', fontSize: '12px', color: '#f59e0b', margin: '15px 0' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Estimated Delivery: Within 7 Days 🚚
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onClick={() => setShowOrderSuccess(false)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      style={{ backgroundColor: '#22c55e', color: '#fff', border: 'none', width: '100%', padding: '10px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Back to Shopping
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }